  Eigen::Matrix<double,1,6> M = Eigen::Matrix<double,1,6>::Zero();
  M(0,0) = 1.0; return M;
};

int best = jmf_.mostLikelyMode();
Eigen::MatrixXd R1(1,1);
R1(0,0) = std::max(1e-6, R_vel_modes_[best](0,0));

jmf_.update(z_enc, h_enc, H_enc, R1);

